Exploring a method
Here we compare some of the approaches. Switch genotypes on and off to compare their coefficients (top); the lower panel shows the held-out error for all settings, as the mean over 20 genotypes.

d3 = window.d3
Plot = window.Plot
hyper = FileAttachment("data/interactive/hyper.json").json()
contrast = ["g181", "g171", "g021", "g141", "g151"]
shades = ["#8B1E3F", "#014E81", "#00A6D6", "#6D8B1E", "#6B7280"]
viewof method = select("Method", Object.keys(hyper.methods), "STLSQ")
spec = hyper.methods[method]
viewof shown = toggles("Genotypes", contrast, shades)
viewof step = slider(spec.param, spec.values, Math.floor(spec.values.length / 2), v =&gt; (+v).toPrecision(2))

































































{
  const all = Object.values(hyper.methods);
  const reach = d3.max(all.flatMap(m =&gt; m.effect.flat(2).map(Math.abs)));
  const rmse = [d3.min(all.flatMap(m =&gt; m.rmse)), 0.8];   // cap: very large penalties are off scale
  const band = 5, n = shown.length;
  const key = (term, name) =&gt; term + "|" + name;
  const domain = hyper.terms.flatMap(term =&gt; [...shown.map(name =&gt; key(term, name)), key(term, "")]);
  const middle = hyper.terms.map(term =&gt; key(term, shown[Math.floor(n / 2)]));
  const rows = shown.flatMap(name =&gt; {
    const g = hyper.genotypes.indexOf(name);
    return hyper.terms.map((term, i) =&gt; ({name, band: key(term, name), effect: spec.effect[step][g][i]}));
  });
  const coefficients = Plot.plot({
    width: 56 + band * domain.length, height: 250, marginLeft: 56, marginBottom: 60,
    y: {domain: [-reach, reach], label: "scaled coefficient", ticks: 4},
    x: {domain, ticks: middle, tickFormat: d =&gt; d.split("|")[0], tickRotate: -90, label: null, padding: 0},
    color: {domain: contrast, range: shades},
    marks: [Plot.barY(rows, {x: "band", y: "effect", fill: "name"}), Plot.ruleY([0])]
  });
  const curve = spec.values.map((value, i) =&gt; ({value, rmse: spec.rmse[i]}));
  const scale = spec.param === "terms" ? "linear" : "log";
  const error = Plot.plot({
    width: 520, height: 220,
    x: {type: scale, label: spec.param, tickFormat: ".2~g"},
    y: {domain: [rmse[0] - 0.01, rmse[1] + 0.01], label: "held-out RMSE (t/ha)"},
    marks: [Plot.line(curve, {x: "value", y: "rmse", stroke: "#9CA3AF", clip: true}),
            Plot.dot(curve, {x: "value", y: "rmse", fill: "#9CA3AF", r: 3, clip: true}),
            Plot.dot([curve[step]], {x: "value", y: "rmse", fill: "#8B1E3F", r: 6, clip: true})]
  });
  return html`&lt;div&gt;&lt;div class="scroll-x"&gt;${coefficients}&lt;/div&gt;${error}&lt;/div&gt;`;
}







